/* Inventário em slots: a arte é separada dos controles e dos dados do personagem. */
(function(){'use strict';const $=id=>document.getElementById(id),C=MythosCore,I=InventoryModel;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const itemIcon=i=>i.slot==='weapon'?14:i.slot==='shield'?15:I.SLOTS.find(s=>s.key===i.slot)?.icon??1;
const coin='<svg viewBox="0 0 36 30" aria-hidden="true"><g stroke="#936419" stroke-width="1"><ellipse cx="12" cy="21" rx="10" ry="6" fill="#be8b29"/><ellipse cx="12" cy="17" rx="10" ry="6" fill="#e1b854"/><ellipse cx="12" cy="13" rx="10" ry="6" fill="#f0cd76"/><ellipse cx="12" cy="13" rx="7" ry="4" fill="none" stroke="#fff0b3"/><ellipse cx="24" cy="23" rx="10" ry="6" fill="#d5a23e"/><ellipse cx="24" cy="21" rx="10" ry="6" fill="#f0cb6b"/><ellipse cx="24" cy="21" rx="7" ry="4" fill="none" stroke="#fff0ad"/></g></svg>';
class MythosInventory{
 constructor(game){this.g=game;this.tab='Normal';this.dropOpen=false;this.selected=null;this.atlas=new Image();this.reference=new Image();this.atlas.onload=()=>this.paint();this.reference.onload=()=>this.paint();this.atlas.src='__INVENTORY_ITEMS__';this.reference.src='__INVENTORY_REFERENCE__';}
 dismiss(){this.dropOpen=false;this.tab='Normal';this.selected=null;const popup=$('coinPopup');if(popup)popup.hidden=true;const main=$('inventoryMain');if(main)main.inert=false;}
 art(kind){return '<canvas width="96" height="96" data-art="'+kind+'" aria-hidden="true"></canvas>';}
 render(tab=this.tab){
  this.tab=tab;this.dropOpen=false;this.selected=null;const p=this.g.p,entries=tab==='Roupas'?[]:I.entries(p);
  let equipment='';
  if(tab==='Normal')equipment=I.SLOTS.map(s=>{const id=p.equipment[s.key],item=C.ITEMS[id];return '<button class="equip-slot '+(item?'filled rarity-'+item.rarity:'empty')+'" data-slot="'+s.key+'" style="left:'+s.x+'%;top:'+s.y+'%" title="'+esc(item?item.name+' · '+s.name:s.name)+'" aria-label="'+esc(s.name+(item?': '+item.name:': vazio'))+'">'+this.art('gear-'+(item?itemIcon(item):s.icon))+'</button>';}).join('');
  else if(tab==='Roupas')equipment='<div class="inventory-empty-state"><span>'+MythosUI.icon('shield')+'</span><p>Você ainda não possui roupas cosméticas.</p></div>';
  else equipment='<section class="inventory-preview"><span>Prévia do equipamento atual</span><canvas id="inventoryPreview" width="240" height="320" aria-label="Visual atual do Guardião"></canvas><div class="preview-hands">'+['weapon','shield'].map(slot=>{const item=C.ITEMS[p.equipment[slot]];return '<button data-hand="'+slot+'" title="'+esc(item?item.name:slot==='weapon'?'Arma: vazio':'Escudo: vazio')+'">'+this.art('gear-'+(slot==='weapon'?14:15))+'</button>';}).join('')+'</div></section>';
  let grid='';for(let n=0;n<I.CAPACITY;n++){const entry=entries[n],item=entry?.kind==='gear'?C.ITEMS[entry.id]:null;grid+='<button class="bag-slot '+(item?'rarity-'+item.rarity:entry?'has-potion':'bag-empty')+'" data-cell="'+n+'" '+(entry?'draggable="'+(entry.kind==='gear')+'" title="'+esc(item?item.name:entry.id==='hp'?'Poção de vida':'Poção de mana')+'"':'aria-label="Espaço vazio '+(n+1)+'"')+'>'+ (entry?this.art(entry.kind==='gear'?'gear-'+itemIcon(item):entry.id)+(entry.kind==='potion'?'<b class="stack-count">'+entry.count+'</b>':''):'')+'</button>';}
  $('modalTitle').textContent='Inventário';
  $('modalBody').innerHTML='<div id="inventoryRoot"><div id="inventoryMain"><h2 class="inventory-title">Inventário</h2><button id="inventoryClose" class="inv-close" title="Fechar inventário [Esc]" aria-label="Fechar inventário">×</button><nav class="inventory-tabs" aria-label="Seções do inventário">'+['Normal','Roupas','Provador'].map(t=>'<button data-inv-tab="'+t+'" class="'+(t===tab?'active':'')+'" aria-pressed="'+(t===tab)+'">'+t+'</button>').join('')+'</nav>'+equipment+'<div class="inv-divider"></div><div class="bag-grid" aria-label="Mochila com 48 espaços">'+grid+'</div><footer class="inventory-footer"><span id="inventoryCapacity">'+entries.length+' / '+I.CAPACITY+'</span><div class="inventory-currency"><button id="coinDropTrigger" title="Soltar moedas" aria-label="Abrir janela Soltar moedas">'+coin+'</button><span id="inventoryGold">'+p.gold.toLocaleString('pt-BR')+'</span></div></footer><section id="inventoryItemDetail" hidden></section></div><section id="coinPopup" role="dialog" aria-modal="true" aria-labelledby="coinPopupTitle" hidden><header><h3 id="coinPopupTitle">Soltar moedas</h3><button id="coinDropClose" aria-label="Fechar janela de moedas">×</button></header><label for="coinDropAmount">Digite o valor:</label><div class="coin-entry"><input id="coinDropAmount" type="text" inputmode="numeric" pattern="[0-9]*" maxlength="16" autocomplete="off" value="0" aria-describedby="coinDropError"><div class="coin-steppers"><button id="coinStepUp" aria-label="Aumentar quantidade">▴</button><button id="coinStepDown" aria-label="Diminuir quantidade">▾</button></div><button id="coinDropMax">Máximo</button></div><p id="coinDropError" role="status"></p><div class="coin-actions"><button id="coinDropOK" disabled>OK</button><button id="coinDropCancel">Cancelar</button></div></section></div>';
  $('inventoryClose').onclick=()=>this.g.close();
  document.querySelectorAll('[data-inv-tab]').forEach(b=>b.onclick=()=>this.render(b.dataset.invTab));
  document.querySelectorAll('[data-cell]').forEach(b=>{const entry=entries[+b.dataset.cell];if(!entry)return;b.onclick=()=>this.showItem(entry);b.ondblclick=()=>this.activate(entry);b.ondragstart=e=>{if(entry.kind==='gear')e.dataTransfer.setData('text/plain',entry.id);};});
  document.querySelectorAll('[data-slot]').forEach(b=>{b.onclick=()=>{const id=p.equipment[b.dataset.slot];if(id)this.showItem({id,kind:'gear',equipped:b.dataset.slot});};b.ondragover=e=>e.preventDefault();b.ondrop=e=>{e.preventDefault();this.equip(e.dataTransfer.getData('text/plain'),b.dataset.slot);};});
  document.querySelectorAll('[data-hand]').forEach(b=>b.onclick=()=>{const id=p.equipment[b.dataset.hand];if(id)this.showItem({id,kind:'gear',equipped:b.dataset.hand});});
  $('coinDropTrigger').onclick=()=>this.openDrop();$('coinDropClose').onclick=() =>this.closeDrop();$('coinDropCancel').onclick=()=>this.closeDrop();$('coinDropMax').onclick=()=>{ $('coinDropAmount').value=String(this.g.p.gold);this.validateAmount();};
  $('coinStepUp').onclick=()=>this.step(1);$('coinStepDown').onclick=()=>this.step(-1);$('coinDropAmount').oninput=()=>this.validateAmount();$('coinDropOK').onclick=()=>this.confirmDrop();
  $('coinPopup').onkeydown=e=>{e.stopPropagation();if(e.code==='Escape'){e.preventDefault();this.closeDrop();}else if(e.code==='Enter'&&e.target===$('coinDropAmount')){e.preventDefault();if(!e.repeat)this.confirmDrop();}};
  this.paint();
 }
 paint(){
  if(this.g.panel!=='inventory')return;document.querySelectorAll('[data-art]').forEach(canvas=>{const art=canvas.dataset.art,ctx=canvas.getContext('2d');ctx.clearRect(0,0,96,96);if(art.startsWith('gear-')){if(!this.atlas.complete||!this.atlas.naturalWidth)return;const index=+art.slice(5),cell=this.atlas.naturalWidth/4;ctx.drawImage(this.atlas,index%4*cell,Math.floor(index/4)*cell,cell,cell,5,5,86,86);}else if(this.reference.complete&&this.reference.naturalWidth){const rect=art==='hp'?[151,874,60,58]:[247,874,58,60];ctx.drawImage(this.reference,...rect,8,8,80,80);}});
  const preview=$('inventoryPreview');if(preview){const c=preview.getContext('2d');c.clearRect(0,0,240,320);c.save();c.translate(120,280);c.scale(2.8,2.8);this.g.renderer.human(c,0,0,Math.PI/2,0,false);c.restore();}
 }
 showItem(entry){
  this.selected=entry;const detail=$('inventoryItemDetail'),p=this.g.p,item=C.ITEMS[entry.id],worn=item&&p.equipment[item.slot]===item.id;
  detail.hidden=false;detail.innerHTML='<button id="itemDetailClose" aria-label="Fechar detalhes">×</button><h3>'+esc(item?item.name:entry.id==='hp'?'Poção de vida':'Poção de mana')+'</h3><p>'+esc(item?item.description:entry.id==='hp'?'Recupera 80 de vida.':'Recupera 60 de mana em 5 segundos.')+'</p>'+(item?'<p class="item-requirements">Nível '+item.minLevel+' · '+Object.entries(item.req).map(([k,v])=>({forca:'Força',destreza:'Destreza',magia:'Magia',vitalidade:'Vitalidade'}[k])+' '+v).join(' · ')+'<br>'+ (item.power?'Poder '+item.power.toFixed(1):'Defesa física '+item.def.toFixed(1))+'</p>':'')+'<button id="itemDetailAction">'+(worn?'Retirar':item?'Equipar':'Usar')+'</button>';
  $('itemDetailClose').onclick=()=>detail.hidden=true;$('itemDetailAction').onclick=()=>worn?this.unequip(item.slot):this.activate(entry);
 }
 activate(entry){if(entry.kind==='gear')this.equip(entry.id);else{this.g.close();this.g.potion(entry.id);}}
 equip(id,targetSlot=null){const item=C.ITEMS[id];if(!item||targetSlot&&item.slot!==targetSlot){this.g.toast('Este item não é compatível com o slot.');return false;}if(!C.equip(this.g.p,id)){this.g.toast('Requisitos de nível ou atributos não atendidos.');return false;}this.g.action=null;this.g.sound.tone(410,.15,'triangle',.02,1.3);this.g.save();this.render();return true;}
 unequip(slot){if(I.entries(this.g.p).length>=I.CAPACITY){this.g.toast('A mochila está cheia.');return false;}this.g.p.equipment[slot]=null;this.g.action=null;if(slot==='shield')this.g.blockTime=0;const s=C.stats(this.g.p);this.g.p.hp=Math.min(s.hp,this.g.p.hp);this.g.p.mp=Math.min(s.mp,this.g.p.mp);this.g.save();this.render();return true;}
 openDrop(){if(this.g.panel!=='inventory')return;this.dropOpen=true;$('inventoryItemDetail').hidden=true;$('inventoryMain').inert=true;$('coinPopup').hidden=false;$('coinDropAmount').value='0';$('coinDropError').textContent=this.g.p.gold<1?'Você não possui moedas para soltar.':'';this.validateAmount();$('coinDropAmount').focus();$('coinDropAmount').select?.();}
 closeDrop(){this.dropOpen=false;const popup=$('coinPopup');if(popup)popup.hidden=true;const main=$('inventoryMain');if(main)main.inert=false;$('coinDropTrigger')?.focus();}
 validateAmount(){const amount=I.dropAmount($('coinDropAmount').value,this.g.p.gold);$('coinDropOK').disabled=amount===null;$('coinDropMax').disabled=this.g.p.gold<1;return amount;}
 step(delta){const field=$('coinDropAmount'),n=Number(field.value);field.value=String(Math.max(0,Math.min(this.g.p.gold,(Number.isSafeInteger(n)?n:0)+delta)));this.validateAmount();}
 confirmDrop(){if(!this.dropOpen)return false;const amount=this.validateAmount();if(amount===null){$('coinDropError').textContent='Informe um número inteiro entre 1 e '+this.g.p.gold.toLocaleString('pt-BR')+'.';return false;}if(!this.g.dropGold(amount)){ $('coinDropError').textContent='Não foi possível soltar as moedas aqui.';return false;}this.closeDrop();this.render();return true;}
}
window.MythosInventory=MythosInventory;
})();
